#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

const int N=10005, S=N-2, T=N-1;
const int M=2000010;
const int INF=2000000000;

int head[N], to[M], nxt[M], capacity[M], cost[M], edgeIdx=1;

void addEdge(int u, int v, int cap, int cst){
	to[++edgeIdx]=v; nxt[edgeIdx]=head[u]; head[u]=edgeIdx;
	capacity[edgeIdx]=cap; cost[edgeIdx]=cst;
	to[++edgeIdx]=u; nxt[edgeIdx]=head[v]; head[v]=edgeIdx;
	capacity[edgeIdx]=0; cost[edgeIdx]=-cst;
}

queue<int> q;
long long dist[N];
bool inQ[N];

bool spfa(){
	memset(inQ, 0, sizeof(inQ));
	memset(dist, 0x3f, sizeof(dist));
	q.push(T); dist[T]=0; inQ[T]=true;
	while(!q.empty()){
		int x=q.front(); q.pop();
		inQ[x]=false;
		for(int i=head[x];i;i=nxt[i]){
			int y=to[i];
			if(capacity[i^1] && dist[y]>dist[x]+cost[i^1]){
				dist[y]=dist[x]+cost[i^1];
				if(!inQ[y]){
					q.push(y);
					inQ[y]=true;
				}
			}
		}
	}
	return dist[S]<1e18;
}

int dfs(int x, int flowLimit, ll &totalCost){
	int flow=0; inQ[x]=true;
	if(x==T) return flowLimit;
	for(int i=head[x];i;i=nxt[i]){
		int y=to[i];
		if(!capacity[i] || inQ[y]) continue;
		if(dist[x]!=dist[y]+cost[i]) continue;
		int t=dfs(y, min(capacity[i], flowLimit - flow), totalCost);
		capacity[i]-=t; capacity[i^1]+=t;
		flow+=t; totalCost+=t*cost[i];
		if(flow==flowLimit) break;
	}
	return flow;
}

long long minCostFlow(){
	int totalFlow=0; ll totalCost=0;
	while(spfa()){
		memset(inQ, 0, sizeof(inQ));
		totalFlow+=dfs(S, 101, totalCost);
	}
	return totalCost;
}

int main(){
	int n,m,k,c,d,limit=101;
	cin>>n>>m>>k>>c>>d;
	for(int i=0;i<k;i++){
		int x; cin>>x; x--;
		addEdge(S,x,1,0);
	}
	for(int i=0;i<limit;i++)
		addEdge(i*n,T,k,c*i);
	for(int i=0;i<n;i++)
		for(int j=0;j<limit-1;j++)
			addEdge(i+j*n,i+(j+1)*n,k,0);
	while(m--){
		int x,y; cin>>x>>y; x--; y--;
		for(int i=0;i<limit-1;i++)
			for(int j=k-1;j>=0;j--){
				addEdge(x+i*n,y+(i+1)*n,1,d*(j*2+1));
				addEdge(y+i*n,x+(i+1)*n,1,d*(j*2+1));
			}
	}
	cout<<minCostFlow();
	return 0;
}
